//! Apparatus-overhead calibration.
//!
//! - Per-iteration loop cost: two-point slope through an empty
//!   bench at two `inner` sizes (`N_LOW`, `N_HIGH`).
//! - Per-sample timer-pair framing: measured directly and
//!   amortized (`FRAMING_PAIRS` pairs per window, min over
//!   `FRAMING_WINDOWS`), so the ~10 ns TSC quantum divides by the
//!   pair count instead of landing on the estimate whole.

use std::hint::black_box;
use std::time::{Duration, Instant};

use crate::harness::Bench;

/// Calibration warmup iterations — long enough for CPU frequency
/// boost to ramp before the first `min_low` measurement.
pub const CAL_WARMUP: u64 = 100_000;

/// Samples per `measure()` call; the reported minimum approaches
/// the hardware floor as samples grow.
pub const CAL_SAMPLES: u64 = 100_000;

/// Inner-loop count for the low-N calibration point.
pub const N_LOW: u64 = 100;

/// Inner-loop count for the high-N calibration point. A wide spread
/// (`N_HIGH / (N_HIGH - N_LOW) ≈ 1.01`) keeps noise amplification on
/// the fitted framing small — the 0.6.0 fix for framing instability.
pub const N_HIGH: u64 = 10_000;

/// Timer pairs per amortized-framing window. The window's ±1-quantum
/// error divides by this — ~0.001 ns at 10,000 with a ~10 ns TSC
/// quantum — vs the full quantum the old un-amortized intercept fit
/// inherited.
pub const FRAMING_PAIRS: u64 = 10_000;

/// Amortized-framing windows measured; the minimum is kept. The min
/// sheds windows inflated by preemption or a frequency dip while
/// staying amortized (each candidate is already a window mean).
pub const FRAMING_WINDOWS: u64 = 100;

/// Apparatus-overhead model fitted by [`calibrate`]. Bench code uses
/// [`Overhead::per_call_ns`] to subtract per-call overhead from
/// reported latencies.
#[derive(Debug)]
pub struct Overhead {
    /// Fixed per-sample timer-pair overhead
    /// (`Instant::now()` before and after a batch), in nanoseconds.
    pub framing_per_sample_ns: f64,
    /// Per-inner-iteration loop overhead (branch + `black_box`),
    /// in nanoseconds.
    pub loop_per_iter_ns: f64,
    /// Raw `min_low` measurement (ns). Preserved for `-v` logging.
    pub cal_min_low_ns: u64,
    /// Raw `min_high` measurement (ns). Preserved for `-v` logging.
    pub cal_min_high_ns: u64,
    /// Wall-clock duration of the full calibration run.
    pub cal_duration: Duration,
}

impl Overhead {
    /// Per-call apparatus overhead at a given `inner`, in nanoseconds:
    /// `framing_per_sample / inner + loop_per_iter`.
    pub fn per_call_ns(&self, inner: u64) -> f64 {
        self.framing_per_sample_ns / inner as f64 + self.loop_per_iter_ns
    }
}

struct EmptyBench;

impl Bench for EmptyBench {
    fn name(&self) -> &str {
        "empty"
    }

    fn step(&mut self) -> u64 {
        black_box(1)
    }
}

/// Run the two-point calibration and return the fitted [`Overhead`].
/// Blocks for ~500 ms on a typical modern x86.
pub fn calibrate() -> Overhead {
    let mut bench = EmptyBench;
    let cal_start = Instant::now();
    for _ in 0..CAL_WARMUP {
        black_box(bench.step());
    }

    let min_low = measure(&mut bench, CAL_SAMPLES, N_LOW);
    let min_high = measure(&mut bench, CAL_SAMPLES, N_HIGH);

    // Two-point slope: per_sample = framing + inner * loop_per_iter,
    // so (min_high - min_low) / (N_HIGH - N_LOW) gives loop_per_iter.
    // The same ±1-2 quanta of slop divides by 9,900, so the slope is
    // steady where the old intercept-fit framing was not.
    let loop_per_iter_ns = if min_high > min_low {
        (min_high - min_low) as f64 / (N_HIGH - N_LOW) as f64
    } else {
        0.0
    };

    // Framing is measured directly and amortized, not fitted: the old
    // intercept (min_low - N_LOW * slope) inherited min_low's full
    // ~10 ns TSC quantum — run-to-run draws spanned 0-21 ns and a
    // negative intercept clamped to 0.0 (see
    // notes/design.md#calibration-accuracy-framing-quantization).
    let framing_per_sample_ns = measure_framing();

    Overhead {
        framing_per_sample_ns,
        loop_per_iter_ns,
        cal_min_low_ns: min_low,
        cal_min_high_ns: min_high,
        cal_duration: cal_start.elapsed(),
    }
}

/// Measure the per-sample timer-pair framing cost, amortized: each
/// window brackets [`FRAMING_PAIRS`] back-to-back `Instant::now()` /
/// `elapsed()` pairs with one outer pair and divides by the count,
/// so the quantization error on a window is q/M; the minimum over
/// [`FRAMING_WINDOWS`] windows is returned.
///
/// - Measures the *throughput* cost of paired reads, which can
///   differ slightly from a pair pipelined around real work — a
///   small bias, but far inside the ~10 ns interval the old
///   min-based fit could not see into.
fn measure_framing() -> f64 {
    let mut min_ns = f64::INFINITY;
    for _ in 0..FRAMING_WINDOWS {
        let window = Instant::now();
        for _ in 0..FRAMING_PAIRS {
            let start = Instant::now();
            black_box(start.elapsed());
        }
        let per_pair = window.elapsed().as_nanos() as f64 / FRAMING_PAIRS as f64;
        if per_pair < min_ns {
            min_ns = per_pair;
        }
    }
    min_ns
}

/// Amortized per-sample cost at a given `inner`: each window times
/// `samples` complete samples (timer pair around an `inner`-iteration
/// loop — the exact shape [`measure`] takes one at a time) and
/// divides by the count, so quantization error is q/samples; the
/// minimum over `windows` windows is returned, in ns.
fn measure_window(bench: &mut EmptyBench, windows: u64, samples: u64, inner: u64) -> f64 {
    let mut min_ns = f64::INFINITY;
    for _ in 0..windows {
        let window = Instant::now();
        for _ in 0..samples {
            let start = Instant::now();
            for _ in 0..inner {
                black_box(bench.step());
            }
            black_box(start.elapsed());
        }
        let per_sample = window.elapsed().as_nanos() as f64 / samples as f64;
        if per_sample < min_ns {
            min_ns = per_sample;
        }
    }
    min_ns
}

/// Return the minimum elapsed ns over `samples` timings of `inner`
/// iterations of the empty bench step.
fn measure(bench: &mut EmptyBench, samples: u64, inner: u64) -> u64 {
    let mut min_ns = u64::MAX;
    for _ in 0..samples {
        let start = std::time::Instant::now();
        for _ in 0..inner {
            black_box(bench.step());
        }
        let e = start.elapsed().as_nanos() as u64;
        if e < min_ns {
            min_ns = e;
        }
    }
    min_ns
}

